// External API compatibility and connection management.
const pdfCeOriginalRequest=x;
x=async function(requestWindow,url,options,label){
  try{
    return await pdfCeOriginalRequest(requestWindow,url,options,label);
  }catch(primaryError){
    const isNetworkFailure=primaryError instanceof b&&primaryError.message.includes('无法连接到 API');
    if(options.signal?.aborted||!isNetworkFailure||typeof y.requestUrl!=='function')throw primaryError;
    try{
      const fallback=await y.requestUrl({
        url,
        method:options.method??'GET',
        headers:options.headers??{},
        body:options.body,
        throw:false
      });
      if(options.signal?.aborted)throw new DOMException('The operation was aborted.','AbortError');
      const response=new Response(fallback.arrayBuffer??fallback.text,{status:fallback.status,headers:fallback.headers});
      if(response.ok)return response;
      const details=await Wt(response);
      throw new b(Ot(label,response.status,details),[400,401,403,404].includes(response.status)?'configure':'retry');
    }catch(fallbackError){
      if(options.signal?.aborted)throw new DOMException('The operation was aborted.','AbortError');
      if(fallbackError instanceof b)throw fallbackError;
      throw primaryError;
    }
  }
};

function pdfCeApiRoot(baseUrl){
  const clean=baseUrl.trim().replace(/\/+$/u,'');
  if(!clean)throw new S('Please configure an API base URL first.');
  Fe(clean);
  return clean.replace(/\/chat\/completions$/iu,'');
}

function pdfCeApiCredentials(plugin,requireModel){
  const root=pdfCeApiRoot(plugin.settings.apiBaseUrl);
  const secretId=plugin.settings.apiKeySecretId.trim();
  if(!secretId)throw new S('Please select an API key secret first.');
  const apiKey=plugin.app.secretStorage.getSecret(secretId);
  if(!apiKey)throw new S(`The API key secret "${secretId}" is unavailable on this device.`);
  const modelId=(plugin.settings.translationModelId||plugin.settings.assistantModelId||'').trim();
  if(requireModel&&!modelId)throw new S('Please add and select a model first.');
  return{root,apiKey,modelId};
}

async function pdfCeRequestJson(url,method,apiKey,body){
  let response;
  try{
    response=await y.requestUrl({
      url,
      method,
      headers:{Authorization:`Bearer ${apiKey}`,'Content-Type':'application/json'},
      ...body?{body:JSON.stringify(body)}:{},
      throw:false
    });
  }catch(error){
    throw new Error(`Unable to reach the API: ${P(error)}`);
  }
  let payload;
  try{payload=response.json??JSON.parse(response.text||'{}')}catch{payload={}}
  if(response.status<200||response.status>=300){
    const message=payload?.error?.message||payload?.message||response.text||`HTTP ${response.status}`;
    throw new Error(`API request failed: ${V(String(message))}`);
  }
  return payload;
}

async function pdfCeFetchModels(plugin){
  const{root,apiKey}=pdfCeApiCredentials(plugin,false);
  const payload=await pdfCeRequestJson(`${root}/models`,'GET',apiKey);
  if(!Array.isArray(payload?.data))throw new Error('The provider did not return an OpenAI-compatible model list.');
  const discovered=payload.data.map(item=>typeof item?.id==='string'?item.id.trim():'').filter(Boolean).sort((a,b)=>a.localeCompare(b));
  if(discovered.length===0)throw new Error('The provider returned an empty model list.');
  const current=new Map(plugin.settings.models.map(item=>[item.id,item]));
  for(const id of discovered)if(!current.has(id))current.set(id,{id,name:id});
  plugin.settings.models=[...current.values()];
  if(!plugin.settings.translationModelId)plugin.settings.translationModelId=discovered[0];
  if(!plugin.settings.assistantModelId)plugin.settings.assistantModelId=plugin.settings.translationModelId;
  await plugin.saveSettings();
  return discovered.length;
}

async function pdfCeTestConnection(plugin){
  const{root,apiKey,modelId}=pdfCeApiCredentials(plugin,true);
  const payload=await pdfCeRequestJson(`${root}/chat/completions`,'POST',apiKey,{
    model:modelId,
    stream:false,
    max_tokens:1,
    messages:[{role:'user',content:'Reply with OK.'}]
  });
  if(!Array.isArray(payload?.choices))throw new Error('The API response is not OpenAI Chat Completions compatible.');
}

const pdfCeOriginalSettingsDisplay=H.prototype.display;
H.prototype.display=function(){
  pdfCeOriginalSettingsDisplay.call(this);
  new y.Setting(this.containerEl).setName('Send PDF page images').setDesc('Enable only for a vision-capable model. When disabled, translation uses extracted PDF text for broader API compatibility.').addToggle(toggle=>toggle.setValue(this.plugin.settings.sendPdfImages===true).onChange(async value=>{
    this.plugin.settings.sendPdfImages=value;
    await this.plugin.saveSettings();
  }));
  new y.Setting(this.containerEl).setName('JSON response format').setDesc('Request OpenAI JSON mode for summaries. Leave disabled if the provider does not support response_format.').addToggle(toggle=>toggle.setValue(this.plugin.settings.useJsonResponseFormat===true).onChange(async value=>{
    this.plugin.settings.useJsonResponseFormat=value;
    await this.plugin.saveSettings();
  }));
  const section=new y.Setting(this.containerEl).setName('API connection tools').setDesc('Fetch available model IDs or verify the selected model and credentials.');
  section.addButton(button=>button.setButtonText('Fetch models').onClick(async()=>{
    button.setDisabled(true).setButtonText('Fetching...');
    try{
      const count=await pdfCeFetchModels(this.plugin);
      new y.Notice(`Imported ${count} model ID${count===1?'':'s'} from the API.`);
      this.display();
    }catch(error){
      new y.Notice(P(error),8000);
      button.setDisabled(false).setButtonText('Fetch models');
    }
  }));
  section.addButton(button=>button.setButtonText('Test connection').setCta().onClick(async()=>{
    button.setDisabled(true).setButtonText('Testing...');
    try{
      await pdfCeTestConnection(this.plugin);
      new y.Notice('API connection succeeded.');
    }catch(error){
      new y.Notice(P(error),8000);
    }finally{
      button.setDisabled(false).setButtonText('Test connection');
    }
  }));
};

// Searchable hierarchical table of contents. Native PDF bookmarks take priority;
// detected headings are used as a fallback for PDFs without embedded bookmarks.
function pdfCeHeadingLevel(title){
  const numbered=/^(\d+(?:\.\d+)*)[.\s]+/u.exec(title);
  return numbered?.[1]?Math.min(numbered[1].split('.').length,6):1;
}

function pdfCeDetectedOutline(pages){
  const flat=[];
  for(const page of pages)for(const block of page.blocks){
    if(block.kind!=='heading')continue;
    const title=M(block).replace(/\s+/gu,' ').trim();
    if(!title||title.length>180||/^published\b/iu.test(title))continue;
    flat.push({title:Le(title),page:page.pageNumber,level:pdfCeHeadingLevel(title),children:[]});
  }
  if(flat.length===0)return pages.map(page=>({title:`Page ${page.pageNumber}`,page:page.pageNumber,level:1,children:[]}));
  const roots=[];
  const stack=[];
  for(const node of flat){
    while(stack.length&&stack[stack.length-1].level>=node.level)stack.pop();
    if(stack.length)stack[stack.length-1].children.push(node);else roots.push(node);
    stack.push(node);
  }
  return roots;
}

async function pdfCeResolveDestination(document,destination){
  try{
    const resolved=typeof destination==='string'?await document.getDestination(destination):destination;
    const reference=Array.isArray(resolved)?resolved[0]:null;
    if(Number.isInteger(reference))return reference+1;
    return reference?await document.getPageIndex(reference)+1:null;
  }catch{return null}
}

async function pdfCeNativeOutline(document,items){
  return Promise.all(items.map(async item=>({
    title:String(item.title||'Untitled section').replace(/\s+/gu,' ').trim(),
    page:await pdfCeResolveDestination(document,item.dest),
    level:1,
    children:await pdfCeNativeOutline(document,Array.isArray(item.items)?item.items:[])
  })));
}

function pdfCeRenderOutline(view,nodes,source){
  const panel=view.contentEl.querySelector('.pdf-translator-outline-panel');
  if(!panel)return;
  panel.empty();
  view.outlineItems.clear();
  const header=panel.createDiv({cls:'pdf-translator-panel-header'});
  header.createEl('h2',{text:'Contents'});
  view.createToolbarButton(header,'panel-left-close','Collapse contents',()=>{
    view.outlineCollapsed=true;
    view.contentEl.addClass('is-outline-collapsed');
  });
  const tools=panel.createDiv({cls:'pdf-translator-outline-tools'});
  const search=tools.createEl('input',{cls:'pdf-translator-outline-search',attr:{type:'search',placeholder:'Search contents','aria-label':'Search contents'}});
  const expandButton=view.createToolbarButton(tools,'list-tree','Collapse all sections',()=>{
    const details=[...panel.querySelectorAll('.pdf-translator-outline-branch')];
    const shouldOpen=details.some(item=>!item.open);
    for(const item of details)item.open=shouldOpen;
    expandButton.setAttribute('aria-label',shouldOpen?'Collapse all sections':'Expand all sections');
    expandButton.toggleClass('is-active',shouldOpen);
  });
  const meta=panel.createDiv({cls:'pdf-translator-outline-meta',text:source});
  const navigation=panel.createEl('nav',{cls:'pdf-translator-outline-list',attr:{'aria-label':'Paper contents'}});
  const renderNodes=(items,parent)=>{
    const list=parent.createEl('ol',{cls:'pdf-translator-outline-tree'});
    for(const node of items){
      const item=list.createEl('li',{cls:'pdf-translator-outline-node'});
      item.dataset.outlineTitle=node.title.toLocaleLowerCase();
      const branch=node.children.length?item.createEl('details',{cls:'pdf-translator-outline-branch',attr:{open:''}}):item;
      const row=node.children.length?branch.createEl('summary',{cls:'pdf-translator-outline-row'}):branch.createDiv({cls:'pdf-translator-outline-row'});
      const button=row.createEl('button',{cls:'pdf-translator-outline-item',text:node.title,attr:{type:'button',title:node.title}});
      if(node.page){
        button.setAttribute('aria-label',`${node.title}, page ${node.page}`);
        button.addEventListener('click',event=>{
          event.preventDefault();
          event.stopPropagation();
          view.translationPages.get(node.page)?.pageEl.scrollIntoView({behavior:'smooth',block:'start'});
        });
        row.createSpan({cls:'pdf-translator-outline-page',text:String(node.page)});
        const tracked=view.outlineItems.get(node.page)??[];
        tracked.push(button);
        view.outlineItems.set(node.page,tracked);
      }else button.disabled=true;
      if(node.children.length)renderNodes(node.children,branch);
    }
    return list;
  };
  renderNodes(nodes,navigation);
  search.addEventListener('input',()=>{
    const query=search.value.trim().toLocaleLowerCase();
    const visit=item=>{
      const childItems=[...item.querySelectorAll(':scope > details > ol > li')];
      const childMatch=childItems.some(visit);
      const ownMatch=!query||(item.dataset.outlineTitle??'').includes(query);
      const visible=ownMatch||childMatch;
      item.toggleClass('is-filtered-out',!visible);
      if(query&&childMatch){const details=item.querySelector(':scope > details');if(details)details.open=true}
      return visible;
    };
    for(const item of navigation.querySelectorAll(':scope > ol > li'))visit(item);
  });
  if(nodes.length===0)navigation.createDiv({cls:'pdf-translator-outline-empty',text:'No contents found.'});
  meta.setAttribute('aria-live','polite');
}

L.prototype.renderOutline=function(pages){
  const fallback=pdfCeDetectedOutline(pages);
  pdfCeRenderOutline(this,fallback,'Detected headings');
  const document=this.pdfDocument;
  const generation=this.loadGeneration;
  if(!document?.getOutline)return;
  document.getOutline().then(async items=>{
    if(!Array.isArray(items)||items.length===0)return;
    const nodes=await pdfCeNativeOutline(document,items);
    if(this.pdfDocument===document&&this.loadGeneration===generation)pdfCeRenderOutline(this,nodes,'PDF bookmarks');
  }).catch(()=>{});
};
